	@Override
	public SuccessRes changeStatusOfFactorType(RatingFieldsMasterChangeStatusReq req) {
		SuccessRes res = new SuccessRes();
		try {
			Date today  = req.getEffectiveDateStart()!=null ?req.getEffectiveDateStart() : new Date();
			Calendar cal = new GregorianCalendar();

			RatingFieldMaster updateRecord = new RatingFieldMaster();
			cal.setTime(today);
			cal.set(Calendar.HOUR_OF_DAY, 23);
			cal.set(Calendar.MINUTE, 1);
			today = cal.getTime();

			List<RatingFieldMaster> list = new ArrayList<RatingFieldMaster>();
			// Find Latest Record
			CriteriaBuilder cb = em.getCriteriaBuilder();
			CriteriaQuery<RatingFieldMaster> query = cb.createQuery(RatingFieldMaster.class);

			// Find All
			Root<RatingFieldMaster> b = query.from(RatingFieldMaster.class);

			// Select
			query.select(b);

			// Effective Date Max Filter
			Subquery<Long> effectiveDate = query.subquery(Long.class);
			Root<RatingFieldMaster> ocpm1 = effectiveDate.from(RatingFieldMaster.class);
			effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
			Predicate a1 = cb.equal(ocpm1.get("productId"), b.get("productId"));
			Predicate a2 = cb.lessThanOrEqualTo(ocpm1.get("effectiveDateStart"), today);
			Predicate a3 = cb.equal(ocpm1.get("ratingId"), b.get("ratingId"));
			effectiveDate.where(a1, a2,a3);

			// Order By
			List<Order> orderList = new ArrayList<Order>();
			orderList.add(cb.desc(b.get("effectiveDateStart")));

			// Where
			Predicate n1 = cb.equal(b.get("effectiveDateStart"), effectiveDate);
			Predicate n2 = cb.equal(b.get("ratingId"), req.getRatingId());
			Predicate n3 = cb.equal(b.get("productId"),req.getProductId());

			query.where(n1, n2,n3).orderBy(orderList);

			// Get Result
			TypedQuery<RatingFieldMaster> result = em.createQuery(query);
			list = result.getResultList();
			updateRecord = list.get(0);

			if (req.getStatus().equalsIgnoreCase("N")) {
				// Delete Old Records
				cal.setTime(today);
				cal.set(Calendar.HOUR_OF_DAY, 23);
				cal.set(Calendar.MINUTE, 30);
				today = cal.getTime();

				// create update
				CriteriaDelete<RatingFieldMaster> delete = cb.createCriteriaDelete(RatingFieldMaster.class);
				Root<RatingFieldMaster> pm = delete.from(RatingFieldMaster.class);

				// Where
				javax.persistence.criteria.Predicate n4 = cb.equal(pm.get("ratingId"), req.getRatingId());
				javax.persistence.criteria.Predicate n5 = cb.greaterThanOrEqualTo(pm.get("effectiveDateStart"), today);
				javax.persistence.criteria.Predicate n6 = cb.equal(pm.get("productId"),req.getProductId());
				delete.where(n4,n5,n6);
				em.createQuery(delete).executeUpdate();
				// Insert Updated Record
				updateRecord.setStatus(req.getStatus());
				factorRepo.save(updateRecord);

			} else if (req.getStatus().equalsIgnoreCase("Y")) {
				// Insert Updated Record
				updateRecord.setStatus(req.getStatus());
				factorRepo.save(updateRecord);
			}
			// perform update

			res.setResponse("Status Changed");
			res.setSuccessId(req.getRatingId());
		} catch (Exception e) {
			e.printStackTrace();
			log.info("Exception is ---> " + e.getMessage());
			return null;
		}
		return res;
	}

	
	
	@Override
	public List<DropDownRes> getRatingFieldsDropdown(RatingDropDownReq req ) {
		List<DropDownRes> resList = new ArrayList<DropDownRes>();
		try {
			Date today = new Date();
			Calendar cal = new GregorianCalendar();
			cal.setTime(today);
			cal.set(Calendar.HOUR_OF_DAY, 23);
			cal.set(Calendar.MINUTE, 1);
			today = cal.getTime();
			cal.set(Calendar.HOUR_OF_DAY, 1);
			cal.set(Calendar.MINUTE, 1);
			Date todayEnd = cal.getTime();
			// Criteria
			CriteriaBuilder cb = em.getCriteriaBuilder();
			CriteriaQuery<RatingFieldMaster> query = cb.createQuery(RatingFieldMaster.class);
			List<RatingFieldMaster> list = new ArrayList<RatingFieldMaster>();

			// Find All
			Root<RatingFieldMaster> c = query.from(RatingFieldMaster.class);

			// Select
			query.select(c);

			// Order By
			List<Order> orderList = new ArrayList<Order>();
			orderList.add(cb.asc(c.get("ratingField")));

			// Effective Date Max Filter
			Subquery<Long> effectiveDate = query.subquery(Long.class);
			Root<RatingFieldMaster> ocpm1 = effectiveDate.from(RatingFieldMaster.class);
			effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
			Predicate a1 = cb.equal(c.get("ratingId"), ocpm1.get("ratingId"));
			Predicate a2 = cb.equal(c.get("productId"),  ocpm1.get("productId"));
			Predicate a3 = cb.lessThanOrEqualTo(ocpm1.get("effectiveDateStart"), today);
			effectiveDate.where(a1,a2,a3);
			// Effective Date End
			Subquery<Long> effectiveDate2 = query.subquery(Long.class);
			Root<RatingFieldMaster> ocpm2 = effectiveDate2.from(RatingFieldMaster.class);
			effectiveDate2.select(cb.max(ocpm2.get("effectiveDateEnd")));
			Predicate a4 = cb.equal(c.get("ratingId"),ocpm2.get("ratingId") );
			Predicate a5 = cb.equal(c.get("productId"),  ocpm2.get("productId"));
			Predicate a6 = cb.greaterThanOrEqualTo(c.get("effectiveDateEnd"), todayEnd);
			effectiveDate2.where(a4,a5,a6);
					
			// Where
			Predicate n1 = cb.equal(c.get("status"), "Y");
			Predicate n2 = cb.equal(c.get("effectiveDateStart"), effectiveDate);
			Predicate n3 = cb.equal(c.get("effectiveDateEnd"), effectiveDate2);
			Predicate n4 = cb.equal(c.get("productId"), req.getProductId());
			query.where(n1, n2,n3,n4).orderBy(orderList);

			// Get Result
			TypedQuery<RatingFieldMaster> result = em.createQuery(query);
			list = result.getResultList();
		// Map
			for (RatingFieldMaster  data : list) {
				// Response
				DropDownRes res = new DropDownRes();
				res.setCode(data.getRatingId().toString());
				res.setCodeDesc(data.getRatingField());
				resList.add(res);
			}
		} catch (Exception e) {
			e.printStackTrace();
			log.info("Exception is ---> " + e.getMessage());
			return null;
		}
		return resList;
	}



